-- Managed table
CREATE TABLE main.sales.orders (id BIGINT, amount DECIMAL(10,2)) USING DELTA;

-- External table at a specific location
CREATE TABLE main.sales.archive
USING DELTA LOCATION '/mnt/archive/orders';

-- View over a query
CREATE VIEW main.sales.big_orders AS
SELECT * FROM main.sales.orders WHERE amount > 1000;
